"use client";

import { Button, Input, Modal } from "@/components/ui";

/**
 * The registration form a class teacher uses to add a child to their class.
 *
 * It intentionally mirrors the school-admin "Add Student" form field for field
 * (names, date of birth, gender, parent/guardian WhatsApp number) so the two
 * flows behave the same; the class is fixed to the roster the teacher opened,
 * and the admission number plus login credentials are generated by the server
 * through the same provisioning path the school admin uses.
 */

export type AddStudentForm = {
  first: string;
  middle: string;
  last: string;
  dob: string;
  gender: string;
  phone: string;
};

export const EMPTY_ADD_FORM: AddStudentForm = {
  first: "",
  middle: "",
  last: "",
  dob: "",
  gender: "",
  phone: "",
};

type Props = {
  isOpen: boolean;
  className?: string;
  form: AddStudentForm;
  onChange: (patch: Partial<AddStudentForm>) => void;
  onClose: () => void;
  onSubmit: () => void;
  saving: boolean;
  error: string | null;
};

export function AddStudentModal({
  isOpen,
  className,
  form,
  onChange,
  onClose,
  onSubmit,
  saving,
  error,
}: Props) {
  const previewName =
    [form.first.trim(), form.middle.trim(), form.last.trim()].filter(Boolean).join(" ") || "—";

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      title="Add Student"
      size="md"
      footer={
        <div className="flex flex-wrap justify-end gap-2">
          <Button variant="ghost" onClick={onClose} disabled={saving}>
            Cancel
          </Button>
          <Button variant="primary" loading={saving} onClick={onSubmit}>
            Add Student
          </Button>
        </div>
      }
    >
      <div className="space-y-4">
        {error && (
          <div className="rounded-lg border border-error bg-error-bg px-4 py-3 text-body text-error">
            {error}
          </div>
        )}

        <div className="rounded-lg border border-border bg-clay px-3 py-2 space-y-0.5">
          <p className="text-caption text-text-secondary">
            Adding to: <span className="text-text-primary font-medium">{className || "—"}</span>
          </p>
          <p className="text-caption text-text-secondary">
            The admission number and login details are generated automatically.
          </p>
        </div>

        <div className="grid grid-cols-1 tablet:grid-cols-3 gap-3">
          <Input
            label="First name"
            value={form.first}
            onChange={(e) => onChange({ first: e.target.value })}
          />
          <Input
            label="Middle name"
            value={form.middle}
            onChange={(e) => onChange({ middle: e.target.value })}
          />
          <Input
            label="Last name"
            value={form.last}
            onChange={(e) => onChange({ last: e.target.value })}
          />
        </div>

        <p className="text-caption text-text-secondary">
          Saved as: <span className="text-text-primary font-medium">{previewName}</span>
        </p>

        <div className="grid grid-cols-1 tablet:grid-cols-2 gap-3">
          <Input
            label="Date of birth"
            type="date"
            value={form.dob}
            onChange={(e) => onChange({ dob: e.target.value })}
          />
          <div>
            <label className="text-caption font-semibold text-text-secondary">Gender</label>
            <select
              value={form.gender}
              onChange={(e) => onChange({ gender: e.target.value })}
              className="w-full mt-1 px-3 py-2.5 border border-border rounded-lg text-body bg-surface focus:outline-none focus:border-primary transition-colors"
            >
              <option value="">Not set</option>
              <option value="male">Male</option>
              <option value="female">Female</option>
            </select>
          </div>
        </div>

        <Input
          label="Parent/Guardian WhatsApp Number"
          value={form.phone}
          placeholder="e.g. 0803 123 4567"
          onChange={(e) => onChange({ phone: e.target.value })}
        />

        <p className="text-caption text-text-secondary">
          Enter at least a first or last name. The child will appear in this class
          immediately, with the same login details every student receives.
        </p>
      </div>
    </Modal>
  );
}
